"""Synchronize the self-contained, Internet-off Kaggle length-only notebook."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
NOTEBOOK = ROOT / "notebooks" / "kaggle_length_submission.ipynb"
FILES = ("baseline.py", "length_baseline.py")


def generated_source_cell():
    lines = [
        "# Generated by python scripts/sync_length_notebook.py; no internet needed on Kaggle.\n",
        "from pathlib import Path\n",
        "import sys\n",
        "source_dir = Path('/kaggle/working/src')\n",
        "source_dir.mkdir(parents=True, exist_ok=True)\n",
        "(source_dir / '__init__.py').write_text('', encoding='utf-8')\n",
    ]
    for filename in FILES:
        content = (ROOT / "src" / filename).read_text(encoding="utf-8")
        lines.append(
            f"(source_dir / {filename!r}).write_text("
            + json.dumps(content, ensure_ascii=False)
            + ", encoding='utf-8')\n"
        )
    lines.extend([
        "sys.path.insert(0, '/kaggle/working')\n",
        "from src.baseline import TARGETS, get_labels\n",
        "from src.length_baseline import fit_length_model, predict_length_model\n",
    ])
    return lines


if __name__ == "__main__":
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--check", action="store_true")
    args = p.parse_args()
    notebook = json.loads(NOTEBOOK.read_text(encoding="utf-8"))
    expected = generated_source_cell()
    if args.check:
        if notebook["cells"][2]["source"] != expected:
            raise SystemExit("Length Notebook is stale: run python scripts/sync_length_notebook.py")
        print("Length Notebook source is up to date")
    else:
        notebook["cells"][2]["source"] = expected
        NOTEBOOK.write_text(json.dumps(notebook, ensure_ascii=False, indent=2) + "\n",
                            encoding="utf-8")
        print("Regenerated", NOTEBOOK)
